wwv_flow_imp_page.create_component_da_action(
 p_id=>wwv_flow_imp.id(21108774408053857)
,p_button_id=>wwv_flow_imp.id(21108330112053853)
,p_action_sequence=>10
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_static_id=>'native-execute-plsql-code'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P3_TARGET_TEXT',
  'items_to_submit', 'P3_SOURCE_TEXT,P3_SOURCE_LANG,P3_TARGET_LANG',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '    l_prompt   clob;',
    '    l_request  clob;',
    '    l_response clob;',
    '    l_json     json_object_t;',
    'begin',
    unistr('    l_prompt := ''\65E5\672C\8A9E\306E\5358\8A9E\300C'' || :P3_SOURCE_TEXT || ''\300D\3092'' ||'),
    unistr('        case :P3_TARGET_LANG when ''en'' then ''\82F1\8A9E'' when ''zh-cn'' then ''\7C21\4F53\4E2D\56FD\8A9E'' when ''ko'' then ''\97D3\56FD\8A9E'' else ''\65E5\672C\8A9E'' end'),
    unistr('        || ''\306B\7FFB\8A33\3057\3066\304F\3060\3055\3044\3002\00A5n\51FA\529B\306F\4EE5\4E0B\306E\5F62\5F0F\306EJSON\3067\8FD4\3057\3066\304F\3060\3055\3044\3002\00A5n\51FA\529B\306FJSON\30C9\30AD\30E5\30E1\30F3\30C8\3060\3051\3092\8FD4\3057\3066\304F\3060\3055\3044\3002\00A5n'),
    '{',
    unistr('    "source_text": "\7FFB\8A33\5BFE\8C61\306E\5358\8A9E",'),
    unistr('    "source_lang": "\7FFB\8A33\5143\306E\8A00\8A9E\FF08\30C7\30D5\30A9\30EB\30C8\306Fja\FF09",'),
    unistr('    "target_lang": "\7FFB\8A33\5148\306E\8A00\8A9E",'),
    unistr('    "target_text": "\7FFB\8A33\3055\308C\305F\5358\8A9E"'),
    '}'';',
    unistr('    /* AI\3078\9001\4FE1\3059\308B\30E1\30C3\30BB\30FC\30B8 */'),
    '    select json_object(',
    '        key ''source_text'' value :P3_SOURCE_TEXT,',
    '        key ''source_lang'' value ''ja'',',
    '        key ''target_lang'' value :P3_TARGET_LANG',
    '    ) into l_request from dual;',
    '    apex_debug.info(l_request);',
    '    l_response := apex_ai.generate(',
    '        p_agent_static_id => ''TRANSLATE_WORD''',
    '        ,p_prompt => l_prompt',
    '    );',
    '    apex_debug.info(l_response);',
    '    l_json := json_object_t.parse(l_response);',
    '    :P3_TARGET_TEXT := l_json.get_string(''target_text'');',
    'end;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_stop_execution_on_error=>true
,p_wait_for_result=>true
,p_created_on=>wwv_flow_imp.dz('20260610031220Z')
,p_updated_on=>wwv_flow_imp.dz('20260610044548Z')
,p_created_by=>'APEXDEV'
,p_updated_by=>'APEXDEV'
);
